type Keys<T> = Record<keyof T, true>;

const NO_DIFFERENCE = { missing: [], extra: [] };

function expectFields(
  registry: SchemaRegistry,
  apiName: string,
  webFields: Record<string, true>,
): void {
  expect(diffFields(registry, apiName, Object.keys(webFields))).toEqual(
    NO_DIFFERENCE,
  );
}

const ENUM_PAIRS: [apiName: string, webValues: readonly string[]][] = [
  ["DiscoverySource", DISCOVERY_SOURCES],
  ["DiscoveryTaskStatus", TASK_STATUSES],
  ["DiscoveryTaskKind", TASK_KINDS],
  ["DiscoveryCandidateStatus", CANDIDATE_STATUSES],
  ["DiscoveryMentionRole", MENTION_ROLES],
  ["DiscoveryArtifactKind", ARTIFACT_KINDS],
  ["SuggestionKind", SUGGESTION_KINDS],
  ["SuggestionStatus", SUGGESTION_STATUSES],
  ["SuggestionSource", SUGGESTION_SOURCES],
  ["SearchMode", SEARCH_MODES],
  ["TranslationSource", TRANSLATION_SOURCES],
  ["DocumentTranslationCode", DOCUMENT_TRANSLATION_CODES],
];

it.each(ENUM_PAIRS)(
  "contract · web arrays equal the API enum %s",
  (apiName, webValues) => {
    expect(diffEnum(API_SCHEMAS, apiName, webValues)).toEqual(NO_DIFFERENCE);
  },
);

