// Known drift, kept visible: the web type sends `accepted` and the API sends
// `score`. Which one the UI should show is a product decision, so this stays
// `it.fails` until it is made.
const TAG_SUPPORT: Keys<DiscoveryTagSupport> = {
  code: true,
  procedures: true,
  share: true,
  accepted: true,
};

it.fails(
  "contract · the web tag support has exactly the API fields (TagSupportRead sends score, not accepted)",
  () => {
    expectFields(API_SCHEMAS, "TagSupportRead", TAG_SUPPORT);
  },
);

// The retired axis names remain here only as a negative contract assertion. The output payloads and
// candidate contracts must not advertise them; the request schema is deliberately not in this list.
const FORBIDDEN_LEGACY_FIELDS = [
  "domain_codes",
  "situation_codes",
  "situation_leaf_codes",
  "direct_domain_confidence",
  "direct_situation_confidence",
];

it.each([
  ["PreviewedDocumentPayload"],
  ["PreviewedSuggestion"],
  ["CandidateMentionItem"],
  ["CandidateMentionRead"],
  ["CandidateDetailResponse"],
  ["CandidateListItemRead"],
])("contract · %s advertises no legacy axis field", (apiName) => {
  const advertised = new Set(propertyNames(API_SCHEMAS, apiName));
  expect(
    FORBIDDEN_LEGACY_FIELDS.filter((field) => advertised.has(field)),
  ).toEqual([]);
});

it("contract · an API response without the new fields still parses", () => {
  const older: CandidateCard = {
    id: "c1",
    key: "passport",
    title: "Passport",
    description: null,
    description_source: null,
    categories: [],
    mention_count: 1,
    confidence: 0.7,
  };

  const page = toDocumentListResponse({
    items: [older],
    total: 1,
    offset: 0,
    limit: 20,
  });

  expect(page.search_mode).toBe("browse");
  expect(page.items[0]).toMatchObject({
    confidence: 0.7,
    similarity: null,
    translation: null,
  });
});

it("contract · responses without the translation field still parse, and the API does not require it", () => {
  const required = new Set(API_SCHEMAS["CandidateCard"].required ?? []);

  expect(required).not.toContain("translation");
  expect(
    toDocumentListResponse({
      items: [
        {
          id: "c1",
          key: "passport",
          title: "Passport",
          description: null,
          description_source: null,
          categories: [],
          mention_count: 1,
          confidence: 0.7,
        },
      ],
      total: 1,
      offset: 0,
      limit: 20,
    }).items[0].translation,
  ).toBeNull();
});

it("contract · the API always sends search_mode and similarity may be absent", () => {
  const required = (name: string) => new Set(API_SCHEMAS[name].required ?? []);

  expect(required("candidate_read_CandidateListResponse")).toContain(
    "search_mode",
  );
  expect(required("CandidateCard")).not.toContain("similarity");
});
